              ...bridge,
              status: bridge.status || "recording",
              bridge_active: true,
              recording: true,
              captured_events: nextEvents,
              captured_browser_events: nextEvents,
              last_recording_steps: nextEvents,
              captured_event_count: nextEvents.length,
              dry_run_ready: false,
              dry_run_result: null,
              last_recording_name: "",
              last_recording_summary: "",
